const cur=$getWorkflowStaticData('global').snapId;
const cutoff=Date.now()-30*60*1000;
const files=($json.value||[]).filter(f=>/^~RT21-snap-/.test(f.name||'')
  && f.id!==cur && new Date(f.createdDateTime||0).getTime()<cutoff);
return files.map(f=>({json:{name:f.name,url:'https://graph.microsoft.com/v1.0/drives/b!GBMH8cf5mk2CZl1ZfpWgDMJRDzREsg1Npw0_haVaoSy_p0-rU6CqTIb8wOlQB4p-'+'/items/'+f.id}}));

// Flag customers whose volume has fallen sharply. Compares like for like:
// day 1..today of this month against day 1..the same day of last month, so the
// signal is meaningful on the 3rd of the month as well as the 30th.
const rows=($json.values||[]).slice(1);          // drop header
const st=$getWorkflowStaticData('global');
const serial=v=>(typeof v==='number')?new Date(Date.UTC(1899,11,30)+v*86400000):null;
const now=new Date();
const Y=now.getUTCFullYear(), M=now.getUTCMonth(), DAY=now.getUTCDate();
const curStart=Date.UTC(Y,M,1), curEnd=Date.UTC(Y,M,DAY,23,59,59);
const prevMonthDays=new Date(Date.UTC(Y,M,0)).getUTCDate();
const prevStart=Date.UTC(Y,M-1,1), prevEnd=Date.UTC(Y,M-1,Math.min(DAY,prevMonthDays),23,59,59);

const agg={};
for(const r of rows){
  const d=serial(r[2]); if(!d) continue;
  const t=d.getTime();
  const inCur = t>=curStart && t<=curEnd;
  const inPrev= t>=prevStart&& t<=prevEnd;
  if(!inCur && !inPrev) continue;
  const no=String(r[8]==null?'':r[8]).trim(); if(!no) continue;
  const name=String(r[9]==null?'':r[9]).trim();
  const rev=Number(r[7])||0, cs=Number(r[5])||0;
  const a=agg[no]||(agg[no]={no,name,curRev:0,curCs:0,prevRev:0,prevCs:0});
  if(name&&!a.name) a.name=name;
  if(inCur){a.curRev+=rev;a.curCs+=cs;} else {a.prevRev+=rev;a.prevCs+=cs;}
}
const MIN_PRIOR=1000, PCT=-0.30;
const drops=Object.values(agg)
  .filter(a=>a.prevRev>=MIN_PRIOR && (a.curRev-a.prevRev)/a.prevRev<=PCT)
  .map(a=>({...a,delta:a.curRev-a.prevRev,pct:(a.curRev-a.prevRev)/a.prevRev}))
  .sort((x,y)=>x.delta-y.delta)
  .slice(0,10);
st.drops=drops;
st.dropWindow={day:DAY,
  cur:new Date(curStart).toISOString().slice(0,10),
  prev:new Date(prevStart).toISOString().slice(0,10)};
const init=$('Init').first().json;
return [{json:{flagged:drops.length, scanned:rows.length,
  url:'https://graph.microsoft.com/v1.0/drives/'+init.driveId+'/items/'+init.fileId+'/content'}}];
